    PARAMETERS
        tile_num = int(), number of tiles of which the atlas is composed
    RETURNS
        scaling_factor = float()
    """
def find_scaling_factor(tile_num: Any) -> object {
    if (tile_num <= 9) {
        return 1.5;
    } elif (tile_num <= 25) {
        return 2.5;
    } elif (tile_num <= 49) {
        return 3.5;
    } elif (tile_num <= 81) {
        return 4.5;
    } elif (tile_num <= 121) {
        return 5.5;
    } elif (tile_num <= 169) {
        return 6.5;
    } else {
        return print(
            ("ERROR :: Unexpected number of tiles for atlas (%s)!" % tile_num)
        );
    }
}

